typedef struct {
    pthread_mutex_t m;      /* private: only the functions below touch it */
    long balance;
    long ops;               /* invariant spans both fields */
} account_t;

void account_credit(account_t *a, long amount) {
    pthread_mutex_lock(&a->m);
    a->balance += amount;
    a->ops++;
    pthread_mutex_unlock(&a->m);
}
